    53: /// Proves durable ownership of an existing link.
    54: ///
    55: /// An existing link is eligible for authoritative mutation or destruction only
    56: /// when its alias is exactly the expected owner tag. A missing tag, a tag from
    57: /// another installation or interface, an unrelated alias, or a duplicate tag on
    58: /// another link all fail closed: interface name and public key are not proof.
    59: fn require_owned(
    60:     observed: &ObservedManagedInterface,
    61:     owner_tag: &OwnerTag,
    62: ) -> Result<(), ReconcileError> {
    63:     if observed.duplicate_owner_tag {
    64:         return Err(ReconcileError::OwnerTagDuplicated);
    65:     }
    66:     match owner_tag.classify(observed.interface_alias.as_deref()) {
    67:         AliasMatch::Owned => Ok(()),
    68:         AliasMatch::Absent => Err(ReconcileError::OwnerTagMissing),
    69:         AliasMatch::ForeignInterface | AliasMatch::ForeignInstallation => {
    70:             Err(ReconcileError::OwnerTagForeign)
    71:         }
    72:         AliasMatch::Unrelated => Err(ReconcileError::OwnerTagMissing),
    73:     }
    74: }
